import { CATALOG, getProduct, money, CART_KEY, validCart, addToCart, quoteCart, createCartOrder, isProductAvailable } from './model.js';
import { icon, esc } from './ui.js';
import { imageFor } from './media-store.js';
import { SPECIALTY_GUIDES, COLLECTIONS } from './specialty-content.js';

const LIBRARY_KEY = 'longshang-demo-library-v1';
const sku = row => `${row.productId}::${row.variant}`;
const categoryLabels = {all:'全部特产',fruit:'水果鲜食',dried:'枸杞干货',vegetable:'田间蔬菜'};
export function createExperience(api) {
  let cart = [], library = {favorites:[],recent:[]}, cartMemoryOnly=false, libraryMemoryOnly=false;
  let specialtyCategory='all', query='', sort='default', committing=false, lastProductPage='';
  function readCart(){if(cartMemoryOnly)return;try{cart=validCart(JSON.parse(localStorage.getItem(CART_KEY)||'[]'));}catch{cartMemoryOnly=true;}}
  function readLibrary(){if(libraryMemoryOnly)return;try{const saved=JSON.parse(localStorage.getItem(LIBRARY_KEY)||'{}');const clean=list=>Array.isArray(list)?[...new Set(list.filter(id=>!!getProduct(id)))].slice(0,20):[];library={favorites:clean(saved?.favorites),recent:clean(saved?.recent)};}catch{libraryMemoryOnly=true;}}
  function saveCart(){try{localStorage.setItem(CART_KEY,JSON.stringify(cart));}catch{cartMemoryOnly=true;api.toast('购物车暂存在本次页面中，关闭后会消失。');}}
  function saveLibrary(){try{localStorage.setItem(LIBRARY_KEY,JSON.stringify(library));}catch{libraryMemoryOnly=true;api.toast('收藏暂存在本次页面中，关闭后会消失。');}}
  readCart();readLibrary();
  function favorite(id){return library.favorites.includes(id);}
  function beforeRender(page,id){const pid=page==='product'?(id||api.selection.productId):'';if(pid===lastProductPage)return;lastProductPage=pid;if(!getProduct(pid))return;readLibrary();if(library.recent[0]===pid)return;library.recent=[pid,...library.recent.filter(x=>x!==pid)].slice(0,20);saveLibrary();}
  function empty(heading,body,route='specialties',label='去特产馆逛逛'){return `<div class="empty-orders"><div class="empty-illustration">${icon('box',52)}</div><h2>${heading}</h2><p>${body}</p><button class="primary" data-action="navigate" data-route="${route}">${label}</button></div>`;}
  function catalogCard(p){return api.productCard(p);}
  function collectionCard(c){return `<button class="collection-card" data-action="navigate" data-route="collection/${c.id}"><img src="${c.image}" alt="${esc(c.title)}示意" loading="lazy"><span class="collection-shade"></span><span class="collection-label">${esc(c.subtitle)}</span><strong>${esc(c.title)}</strong><span class="collection-arrow">${icon('arrow',17)}</span></button>`;}
  function decorateHome(html){const discoveries=`<section class="discovery-section"><div class="section-heading"><div><h2>换个方式，逛家乡</h2><p>按一顿饭、一份果盘，找到喜欢的味道</p></div><button class="text-link" data-action="navigate" data-route="specialties">特产馆 ${icon('arrow',13)}</button></div><div class="collection-strip">${COLLECTIONS.map(collectionCard).join('')}</div><button class="field-notes-entry" data-action="navigate" data-route="guide/jingtai-apple"><span>好物小课堂</span><div><h3>苹果不是越大越好，<br>先看清你买的规格。</h3><p>从果径、净重到包装，带你看懂商品页。</p></div>${icon('arrow',20)}</button></section>`;return html.replace('<div class="category-tabs catalog-tabs"',`${discoveries}<div class="category-tabs catalog-tabs"`);}
  function specialties(){let visible=CATALOG.filter(p=>isProductAvailable(p)&&(specialtyCategory==='all'||p.category===specialtyCategory)&&(!query||[p.name,p.subtitle,p.summary,...p.tags].join(' ').includes(query)));if(sort==='price-asc')visible.sort((a,b)=>a.variants[0].price-b.variants[0].price);if(sort==='price-desc')visible.sort((a,b)=>b.variants[0].price-a.variants[0].price);return `<section class="specialties-page"><div class="museum-heading"><span class="eyebrow">TASTES OF HOME</span><h1>一方风物，<br>慢慢认识。</h1><p>先了解，再挑选。把家乡味道带回日常。</p><span class="museum-number">${String(CATALOG.filter(isProductAvailable).length).padStart(2,'0')}<small>款好物 / 模拟</small></span></div><form id="specialty-search" class="search-form"><span>${icon('search',18)}</span><input name="keyword" aria-label="搜索特产" placeholder="搜苹果、枸杞、家常食材…" value="${esc(query)}" maxlength="40" autocomplete="off"><button type="submit">搜索</button></form><div class="museum-categories" role="group" aria-label="特产分类">${Object.entries(categoryLabels).map(([id,label])=>`<button data-action="x-category" data-category="${id}" aria-pressed="${specialtyCategory===id}" class="${specialtyCategory===id?'active':''}">${label}</button>`).join('')}</div><div class="museum-toolbar"><div><strong>${query?`“${esc(query)}”`:'全部都是家乡味'}</strong><small>${visible.length} 款特产</small></div><select id="specialty-sort" aria-label="商品排序"><option value="default" ${sort==='default'?'selected':''}>推荐顺序</option><option value="price-asc" ${sort==='price-asc'?'selected':''}>模拟价从低到高</option><option value="price-desc" ${sort==='price-desc'?'selected':''}>模拟价从高到低</option></select></div>${query?'<button class="text-link" data-action="x-reset-search">清除搜索，看看全部</button>':''}${visible.length?`<div class="catalog-grid">${visible.map(catalogCard).join('')}</div>`:`<div class="empty-orders"><div class="empty-illustration">${icon('search',42)}</div><h2>没有找到这份味道</h2><p>换个关键词，或清除搜索查看全部特产。</p><button class="primary" data-action="x-reset-search">查看全部特产</button></div>`}<div class="museum-section"><div class="section-heading"><div><h2>按场景挑好物</h2><p>把选择变简单，每份日常都有风味</p></div></div><div class="scene-list">${COLLECTIONS.map(c=>`<button data-action="navigate" data-route="collection/${c.id}"><img src="${c.image}" alt="${esc(c.title)}示意"><span><small>${esc(c.subtitle)}</small><strong>${esc(c.title)}</strong><em>${c.productIds.map(getProduct).filter(isProductAvailable).length} 款可选好物</em></span>${icon('arrow',17)}</button>`).join('')}</div></div><div class="museum-section"><div class="section-heading"><div><h2>特产详情 · 好物指南</h2><p>怎么挑、怎么吃，也值得讲清楚</p></div></div><div class="guide-list">${SPECIALTY_GUIDES.map(g=>`<button data-action="navigate" data-route="guide/${g.id}"><span>${icon('book',19)}</span><div><small>${esc(g.kicker)}</small><h3>${esc(g.title)}</h3></div>${icon('arrow',15)}</button>`).join('')}</div></div><p class="page-footnote">先从景泰起步，其他产区待有真实货源后逐步加入。</p></section>`;}
  function guide(id){const g=SPECIALTY_GUIDES.find(g=>g.id===id),p=getProduct(id);if(!g||!p)return api.title('特产详情','specialties')+empty('这份指南暂未收录','先看看特产馆中的六款好物。');return `${api.title('特产详情','specialties')}<article class="guide-page"><div class="guide-hero"><img src="${esc(imageFor(p))}" alt="${esc(p.name)}示意"><span>好物指南 · 图片示意</span></div><div class="guide-body"><span class="eyebrow">${esc(g.kicker)}</span><h1>${esc(g.title)}</h1><p class="guide-intro">${esc(g.intro)}</p><div class="flavor-card">${icon('sun',22)}<div><span>先认识这一口</span><p>${esc(g.flavor)}</p></div></div><section class="guide-section"><span class="section-index">01</span><h2>怎么挑，才合适？</h2><ol class="selection-tips">${g.selectionTips.map((t,i)=>`<li><b>${i+1}</b><p>${esc(t)}</p></li>`).join('')}</ol></section><section class="guide-section"><span class="section-index">02</span><h2>家常吃法，不必复杂</h2><div class="recipe-grid">${g.uses.map(u=>`<div><span>${icon('bowl',22)}</span><h3>${esc(u.name)}</h3><p>${esc(u.description)}</p></div>`).join('')}</div></section><section class="guide-section"><span class="section-index">03</span><h2>挑选前，常问这些</h2><div class="guide-faq">${g.faq.map(f=>`<details><summary>${esc(f.q)}<span>+</span></summary><p>${esc(f.a)}</p></details>`).join('')}</div></section><section class="guide-section"><h2>也适合放进这份日常</h2><div class="catalog-grid">${g.pairingIds.map(getProduct).filter(isProductAvailable).map(catalogCard).join('')}</div></section><p class="page-footnote">${esc(g.notes)}</p></div></article><div class="guide-purchase"><div><strong>${esc(p.name)}</strong><span>查看规格、介绍与模拟价格</span></div><button class="primary" data-action="view-product" data-product="${p.id}">去看商品 ${icon('arrow',14)}</button></div>`;}
  function collection(id){const c=COLLECTIONS.find(c=>c.id===id);if(!c)return api.title('好物专题','specialties')+empty('这份专题暂未收录','可以先去特产馆看看。');return `${api.title('好物专题','specialties')}<section class="collection-page"><div class="collection-hero"><img src="${c.image}" alt="${esc(c.title)}示意"><div></div><span>${esc(c.subtitle)}</span><h1>${esc(c.title)}</h1></div><div class="collection-body"><p class="body-copy">${esc(c.description)}</p><p class="collection-note">自由搭配，按商品单独选规格；没有预设礼盒或套餐优惠。</p><div class="catalog-grid">${c.productIds.map(getProduct).filter(isProductAvailable).map(catalogCard).join('')}</div><div class="collection-help"><h3>喜欢的先收藏，想买的放进购物车。</h3><p>可以把不同好物一起挑好，再进入购物车核对规格和金额。</p><button class="secondary" data-action="navigate" data-route="cart">去购物车 ${icon('arrow',14)}</button></div></div></section>`;}
  function detailExtras(p){const g=SPECIALTY_GUIDES.find(g=>g.id===p.id);if(!g)return '';return `<section class="surface product-guide-teaser"><div class="section-line"><h2>不只看规格，也看怎么选</h2><span>${icon('book',19)}</span></div><p class="body-copy">${esc(g.flavor)}</p><div class="detail-tip"><span>挑选小提示</span><p>${esc(g.selectionTips[0])}</p></div><div class="recipe-mini">${g.uses.map(u=>`<div><strong>${esc(u.name)}</strong><p>${esc(u.description)}</p></div>`).join('')}</div><button class="text-link" data-action="navigate" data-route="guide/${p.id}">查看完整特产详情 · 挑选与吃法 ${icon('arrow',14)}</button></section>`;}
  function favoriteButton(p){return `<button class="service-button favorite-button ${favorite(p.id)?'is-favorite':''}" data-action="x-favorite" data-product="${p.id}" aria-pressed="${favorite(p.id)}" aria-label="${favorite(p.id)?'取消收藏':'收藏'}${esc(p.name)}">${icon('heart')}<span>${favorite(p.id)?'已收藏':'收藏'}</span></button>`;}
  function productBar(p,x){return `<div class="purchase-bar product-v3-bar"><button class="service-button" data-action="navigate" data-route="cart" aria-label="查看购物车">${icon('cart')}<span>购物车</span></button>${favoriteButton(p)}<button class="secondary add-cart-button" data-action="x-add-cart" ${isProductAvailable(p)?'':'disabled'}>加入购物车</button><button class="primary" data-action="checkout" ${isProductAvailable(p)?'':'disabled'}>${isProductAvailable(p)?'立即选购':'暂未上架'}</button></div>`;}
  function mine(){const orders=api.getOrders();const afterCount=orders.filter(o=>o.afterSale?.status==='submitted').length;return `<section class="mine-page"><div class="mine-profile"><span class="profile-avatar">陇</span><div><span class="eyebrow">好物相伴的每一天</span><h1>你好，体验用户</h1><p>不用登录，先把喜欢的生活逛一遍。</p></div><span class="local-badge">本机演示</span></div><div class="mine-stats"><button data-action="navigate" data-route="favorites"><strong>${library.favorites.length}</strong><span>我的收藏</span></button><button data-action="navigate" data-route="history"><strong>${library.recent.length}</strong><span>浏览足迹</span></button><button data-action="navigate" data-route="cart"><strong>${cart.reduce((a,b)=>a+b.quantity,0)}</strong><span>购物车好物</span></button></div><div class="mine-orders"><div class="section-line"><h2>我的订单</h2><button class="text-link" data-action="go-orders">全部订单 ${icon('arrow',13)}</button></div><div class="order-shortcuts"><button data-action="x-orders" data-filter="all">${icon('orders',25)}<span>全部订单</span><small>${orders.length} 笔</small></button><button data-action="x-orders" data-filter="created">${icon('box',25)}<span>已生成</span><small>${orders.filter(o=>o.status==='created').length} 笔</small></button><button data-action="x-orders" data-filter="aftersale">${icon('heart',25)}<span>售后服务</span><small>${afterCount} 笔待处理</small></button><button data-action="support">${icon('chat',25)}<span>订单客服</span><small>演示咨询</small></button></div></div><div class="mine-menu"><button data-action="navigate" data-route="favorites">${icon('heart',21)}<span>我的收藏<small>喜欢的先留住</small></span>${icon('arrow',15)}</button><button data-action="navigate" data-route="history">${icon('clock',21)}<span>最近看过<small>找回刚才心动的好物</small></span>${icon('arrow',15)}</button><button data-action="address">${icon('pin',21)}<span>示例收货地区<small>${api.addressLabel()} · 不录入真实资料</small></span>${icon('arrow',15)}</button><button data-action="support">${icon('chat',21)}<span>客服与帮助<small>规格、配送和售后问题</small></span>${icon('arrow',15)}</button><button data-action="about">${icon('leaf',21)}<span>关于陇上鲜集<small>从景泰出发，认识各地好物</small></span>${icon('arrow',15)}</button></div><a class="merchant-entry" href="admin.html#/dashboard">${icon('box',21)}<span>商家管理后台<small>改商品、换素材、处理模拟订单</small></span>${icon('arrow',15)}</a><button class="mine-guide-banner" data-action="navigate" data-route="specialties"><span>好物小课堂</span><strong>买之前，先认识它。</strong><p>特产介绍 · 挑选建议 · 家常吃法 ${icon('arrow',14)}</p></button><p class="page-footnote">${libraryMemoryOnly||cartMemoryOnly?'部分数据仅保留至页面关闭。':'收藏、购物车和足迹保存在本浏览器。'}<br>不含真实支付、物流或会员权益。</p></section>`;}
  function savedPage(type){const isFav=type==='favorites';const ids=isFav?library.favorites:library.recent;return `${api.title(isFav?'我的收藏':'浏览足迹','mine')}<section class="saved-page"><div class="section-heading"><div><h2>${isFav?'留住喜欢的味道':'刚刚认识的好物'}</h2><p>${isFav?'收藏后，下次更容易找到。':'按最近浏览排序，仅记录本浏览器。'}</p></div><span>${ids.length} 款</span></div>${ids.length?`<div class="catalog-grid">${ids.map(id=>{const p=getProduct(id);return `<div class="saved-product">${catalogCard(p)}${isFav?`<button class="saved-remove" data-action="x-favorite" data-product="${id}" aria-label="取消收藏${esc(p.name)}">${icon('heart',16)} 已收藏</button>`:''}</div>`;}).join('')}</div>${!isFav?'<button class="text-link danger-link" data-action="x-clear-history">清空浏览足迹</button>':''}`:empty(isFav?'喜欢的好物，留在这里':'还没有留下足迹',isFav?'到商品详情点一下“收藏”，下次就能直接找到。':'先去特产馆，打开一款商品看看。')}<p class="page-footnote">没有账号同步，记录仅在本浏览器可见。</p></section>`;}
  function cartPage(){const chosen=cart.filter(r=>r.selected);const amount=quoteCart(cart,api.selection.address);const all=cart.length>0&&chosen.length===cart.length;return `<section class="cart-page"><div class="cart-heading"><span class="eyebrow">YOUR MARKET BASKET</span><h1>把喜欢的，<br>装进这一篮。</h1><p>${cart.length?`已放入 ${cart.length} 个规格，慢慢挑，确认后再下单。`:'从一份家乡好物，开始今天的挑选。'}</p></div>${cart.length?`<div class="cart-shop"><span>${icon('leaf',18)} 陇上鲜集 · 演示店铺</span><button class="text-link" data-action="x-toggle-all">${all?'取消全选':'全选商品'}</button></div><div class="cart-list">${cart.map(row=>{const p=getProduct(row.productId),v=p.variants.find(v=>v.id===row.variant);return `<article class="cart-item"><label class="cart-check"><input type="checkbox" data-cart-select="${sku(row)}" ${row.selected?'checked':''} aria-label="选择${esc(p.name)}${esc(v.label)}"></label><button class="cart-item-image" data-action="view-product" data-product="${p.id}" aria-label="查看${esc(p.name)}"><img src="${esc(imageFor(p))}" alt="${esc(p.name)}示意"></button><div class="cart-item-copy"><h2>${esc(p.name)}</h2>${!isProductAvailable(p)?'<span class="unavailable-label">暂未上架，请取消勾选或移除</span>':''}<p>${esc(v.label)} · ${esc(v.weight)}</p><strong>¥${money(v.price)} <small>模拟单价</small></strong><div class="cart-item-controls"><div class="stepper"><button data-action="x-cart-quantity" data-key="${sku(row)}" data-delta="-1" aria-label="减少${esc(p.name)}${esc(v.label)}" ${row.quantity<=1?'disabled':''}>−</button><span>${row.quantity}</span><button data-action="x-cart-quantity" data-key="${sku(row)}" data-delta="1" aria-label="增加${esc(p.name)}${esc(v.label)}" ${row.quantity>=10?'disabled':''}>+</button></div><button class="cart-remove" data-action="x-cart-remove" data-key="${sku(row)}">移除</button></div></div></article>`;}).join('')}</div><div class="cart-explainer">${icon('truck',18)}<p>模拟合并结算，运费在下一步计算一次。<br>每个规格最多 10 份；未选中的好物会继续保留。</p></div>`:empty('购物车还是空的','打开商品选择规格后，点击“加入购物车”。')}<div class="cart-recommend"><div class="section-heading"><div><h2>再带一份家乡味</h2><p>这些也可以一起挑选</p></div></div><div class="catalog-grid">${CATALOG.filter(p=>isProductAvailable(p)&&!cart.some(c=>c.productId===p.id)).slice(0,2).map(catalogCard).join('')}</div></div></section>${cart.length?`<div class="cart-total-bar"><label><input type="checkbox" data-cart-all ${all?'checked':''}>全选</label><div><small>已选 ${amount.quantity} 份 · 不含运费</small><strong>¥${money(amount.subtotal)}</strong></div><button class="primary" data-action="x-cart-checkout" ${chosen.length&&amount.available?'':'disabled'}>去结算 (${chosen.length})</button></div>`:''}`;}
  function cartCheckout(){const x=quoteCart(cart,api.selection.address);if(!x.items.length)return api.title('确认模拟订单','cart')+empty('还没有选中商品','返回购物车勾选需要一起购买的好物。','cart','返回购物车');return `${api.title('确认模拟订单','cart')}<section class="cart-checkout-page"><div class="flow-label"><span>01 挑选好物</span><i></i><b>02 合并确认</b><i></i><span>03 完成</span></div><button class="address-card" data-action="address"><span class="address-icon">${icon('pin',25)}</span><div><span class="small-pill">示例收货信息</span><h2>${x.address.person}<small>${x.address.label}</small></h2><p>${x.address.address}</p><small>不需要填写真实个人资料</small></div>${icon('arrow',17)}</button><div class="surface cart-order-items"><div class="seller-line">${icon('leaf',16)} ${x.items.length} 个规格，一笔演示订单</div>${x.items.map(item=>api.miniProduct(item)).join('')}</div><div class="surface"><h2>费用明细 <span class="soft-label">模拟金额</span></h2><dl class="bill"><div><dt>${x.quantity} 份商品合计</dt><dd>¥${money(x.subtotal)}</dd></div><div><dt>演示运费 · 本单仅收一次</dt><dd>${x.shipping===null?'待确认配送':`¥${money(x.shipping)}`}</dd></div><div class="bill-total"><dt>合计</dt><dd>${x.total===null?'暂不可下单':`¥${money(x.total)}`}</dd></div></dl><p class="shipping-note">${!x.available?'选中的商品暂未上架，请返回购物车调整。':x.shipping===null?'请选择甘肃或陕西示例收货地区。':'本次把选中商品合为一笔模拟订单。实际运费和能否合箱以后按货源与物流方案确定。'}</p></div><div class="demo-explainer">${icon('check',18)}<div><strong>只体验流程，不会扣款</strong><p>订单生成后，可查看全部商品明细，并对整笔订单体验售后。未选中的商品保留在购物车。</p></div></div></section><div class="purchase-bar checkout-bar"><div><small>模拟合计</small><strong>${x.total===null?'待确认':`¥${money(x.total)}`}</strong></div><button class="primary" data-action="x-cart-submit" ${x.total===null||committing?'disabled':''}>生成模拟订单</button></div>`;}
  const routes={specialties,guide,collection,mine,cart:cartPage,'cart-checkout':cartCheckout,favorites:()=>savedPage('favorites'),history:()=>savedPage('history')};
  function handleClick(d,button){switch(d.action){
    case 'x-category':specialtyCategory=d.category;api.render();return true;
    case 'x-reset-search':query='';specialtyCategory='all';sort='default';api.render();return true;
    case 'x-favorite':{readLibrary();if(!getProduct(d.product))return true;const already=favorite(d.product);library.favorites=already?library.favorites.filter(x=>x!==d.product):[d.product,...library.favorites];saveLibrary();api.render(true);api.toast(already?'已取消收藏':'已放进我的收藏');return true;}
    case 'x-clear-history':api.showModal('清空本浏览器的浏览足迹？','<div class="modal-copy"><p>收藏与订单会继续保留。</p><div class="modal-actions"><button class="secondary" data-action="close-modal">先保留</button><button class="primary" data-action="x-confirm-clear-history">清空足迹</button></div></div>');return true;
    case 'x-confirm-clear-history':readLibrary();library.recent=[];saveLibrary();api.closeModal();api.render();return true;
    case 'x-orders':api.openOrders(d.filter);return true;
    case 'x-add-cart':{readCart();const s=api.selection;const old=cart.find(r=>r.productId===s.productId&&r.variant===s.variant);const capped=(old?.quantity||0)+s.quantity>10;try{cart=addToCart(cart,s);}catch(error){api.toast(error.message);return true;}saveCart();api.updateTabs();api.toast(capped?'这个规格最多 10 份，购物车已保留 10 份':'已加入购物车，可继续挑选其他好物');return true;}
    case 'x-cart-quantity':readCart();cart=cart.map(row=>sku(row)===d.key?{...row,quantity:Math.min(10,Math.max(1,row.quantity+Number(d.delta)))}:row);saveCart();api.render(true);return true;
    case 'x-cart-remove':readCart();cart=cart.filter(row=>sku(row)!==d.key);saveCart();api.render(true);api.toast('已移出购物车');return true;
    case 'x-toggle-all':readCart();{const all=cart.every(r=>r.selected);cart=cart.map(r=>({...r,selected:!all}));saveCart();api.render(true);}return true;
    case 'x-cart-checkout':api.nav('cart-checkout');return true;
    case 'x-cart-submit':{if(committing||api.route()[0]!=='cart-checkout')return true;committing=true;button.disabled=true;try{readCart();const order=createCartOrder(cart,api.selection.address,api.newId('DEMO'));api.addOrder(order);cart=cart.filter(row=>!row.selected);saveCart();api.nav(`order/${order.id}`);}catch(e){api.toast(e.message);}finally{committing=false;if(api.route()[0]==='cart-checkout')api.render(true);}return true;}
  }return false;}
  function handleChange(target){if(target.id==='specialty-sort'){sort=target.value;api.render(true);return true;}if(target.matches('[data-cart-select]')){readCart();const key=target.dataset.cartSelect;cart=cart.map(r=>sku(r)===key?{...r,selected:target.checked}:r);saveCart();api.render(true);return true;}if(target.matches('[data-cart-all]')){readCart();cart=cart.map(r=>({...r,selected:target.checked}));saveCart();api.render(true);return true;}return false;}
  function handleSubmit(event){if(event.target.id==='specialty-search'){event.preventDefault();query=String(new FormData(event.target).get('keyword')||'').trim().slice(0,40);api.render();return true;}return false;}
  function storage(event){if([CART_KEY,LIBRARY_KEY,null].includes(event.key)){readCart();readLibrary();api.render(true);}}
  return {refresh:()=>{readCart();readLibrary();},routes,beforeRender,decorateHome,detailExtras,productBar,handleClick,handleChange,handleSubmit,storage,count:()=>cart.reduce((a,r)=>a+r.quantity,0),favorites:()=>library.favorites.length};
}
